import {materials,byId,families,networks,journeys,journeyById,locations,sources,articles,glossary,regions,getMaterials,normalize,processNote} from './data.js';
import {scienceTopics,diameterFromDenier,scienceFor} from './science.js';
import {Globe} from './globe.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',compare:'<path d="M8 3v18M16 3v18M3 7h10M11 17h10"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',reset:'<path d="M4 5v6h6M4 11a8 8 0 1 1 2 7"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12v9h14v-9"/>',check:'<path d="m5 12 4 4L19 6"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;}
const brandMark='<svg class="mark" viewBox="0 0 44 48" fill="none" aria-hidden="true"><path d="M6 39V8h30M6 18h27M6 28h20M16 8v31M26 8v21M36 8v11" stroke="currentColor" stroke-width="1.7"/><path d="M9 43c13-2 23-9 29-22" stroke="currentColor" stroke-width="1.2"/></svg>';
const app=$('#app');let globe=null;let saved=[];let persist=true;let lastTitle='';let toastTimer;let atlasFilter={q:'',family:'All materials',sort:'featured'};
try{const value=JSON.parse(localStorage.getItem('fibersOfEarth.saved.v2')||'[]');saved=Array.isArray(value)?value.filter(id=>byId[id]):[];}catch{persist=false;}
const isSaved=id=>saved.includes(id);
function saveButton(id,cls='button small'){return `<button class="${cls}" data-save="${id}" aria-pressed="${isSaved(id)}" aria-label="${isSaved(id)?'Unsave':'Save'} ${esc(byId[id].name)}">${icon('bookmark')}${cls.includes('icon-btn')?'':isSaved(id)?'Saved':'Save material'}</button>`;}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function toggleSave(id){if(!byId[id])return;saved=isSaved(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('fibersOfEarth.saved.v2',JSON.stringify(saved));}catch{persist=false;}$$(`[data-save="${id}"]`).forEach(b=>{b.setAttribute('aria-pressed',isSaved(id));b.setAttribute('aria-label',(isSaved(id)?'Unsave ':'Save ')+byId[id].name);if(!b.classList.contains('icon-btn'))b.innerHTML=icon('bookmark')+(isSaved(id)?'Saved':'Save material');});toast((isSaved(id)?'Saved to your collection.':'Removed from your collection.')+(!persist?' Saved for this session only.':''));if(route().page==='saved')render(false);}
function route(){try{const raw=location.hash.slice(1)||'/atlas/wool';const [p,q='']=raw.split('?');const parts=p.split('/').filter(Boolean).map(decodeURIComponent);return {page:parts[0]||'atlas',id:parts[1],tab:parts[2],params:new URLSearchParams(q)};}catch{return{page:'not-found',params:new URLSearchParams()};}}
function setQuery(values){const r=route();Object.entries(values).forEach(([k,v])=>{if(v===''||v==null||v==='All materials'||v==='featured'||v===1)r.params.delete(k);else r.params.set(k,String(v));});const path=location.hash.split('?')[0]||'#/atlas/wool';history.replaceState(null,'',path+(r.params.size?'?'+r.params.toString():''));}
function href(page,id='',params={}){const q=new URLSearchParams(params);return '#/'+page+(id?'/'+id:'')+(q.size?'?'+q:'');}
function title(text){document.title=text==='Atlas'?'Fibers of Earth | A field guide to what we wear':text+' | Fibers of Earth';lastTitle=text;}
function sourceList(ids){return `<ul class="source-links">${[...new Set(ids)].map(id=>{const s=sources.find(s=>s.id===id);return s?`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a><small>${esc(s.title)}</small></li>`:'';}).join('')}</ul>`;}
function swatch(m,extra=''){return `<div class="swatch-art ${['wool','cashmere','alpaca'].includes(m.id)?'wool':m.id==='silk'?'silk':''} ${extra}" style="--swatch:${m.color}" aria-hidden="true"><span class="fiber-ring"></span></div>`;}
function breadcrumb(items){return `<nav class="breadcrumb" aria-label="Breadcrumb"><a href="#/atlas/wool">Home</a>${items.map(([label,link])=>`<span aria-hidden="true">/</span>${link?`<a href="${link}">${esc(label)}</a>`:`<span>${esc(label)}</span>`}`).join('')}</nav>`;}
function empty(heading,body){return `<div class="empty"><h2>${heading}</h2><p>${body}</p><a class="button" href="#/materials">Explore the material library ${icon('arrow')}</a></div>`;}
function shell(r){const mainGroup=['materials','fiber','compare','saved','brands'].includes(r.page)?'Materials':['journeys','journey','regions','region'].includes(r.page)?'Journeys':['learn','article','science','history','glossary','sources','about','privacy'].includes(r.page)?'Learn':'Atlas';
 let sub=[];
 if(mainGroup==='Materials')sub=[['Library','materials'],['Brands & technologies','brands'],['Compare','compare'],['Saved materials','saved']];
 if(mainGroup==='Journeys')sub=[['Route library','journeys'],['Places & regions','regions']];
 if(mainGroup==='Learn')sub=[['Field notes','learn'],['Science lab','science'],['Fiber histories','history'],['Glossary','glossary'],['Sources & method','sources']];
 app.innerHTML=`<header class="site-header"><a class="logo" href="#/atlas/wool" aria-label="Fibers of Earth home">${brandMark}<span class="logo-text"><span>Fibers</span><span>of Earth</span></span></a><nav class="primary-nav" aria-label="Main navigation">${[['Atlas','atlas/wool'],['Materials','materials'],['Journeys','journeys'],['Learn','learn']].map(([name,url])=>`<a href="#/${url}" ${mainGroup===name?'aria-current="page"':''}>${name}</a>`).join('')}</nav><div class="header-tools"><a class="icon-btn" href="#/compare" aria-label="Compare materials">${icon('compare')}</a><a class="icon-btn" href="#/saved" aria-label="Saved materials">${icon('bookmark')}</a><button class="search-open icon-btn-mobile" data-action="search" aria-label="Search the atlas">${icon('search')}<span>Search</span><kbd>/</kbd></button></div></header>${sub.length?`<nav class="subnav" aria-label="${mainGroup} sections">${sub.map(([name,url])=>`<a href="#/${url}" ${r.page===url?'aria-current="page"':''}>${name}</a>`).join('')}</nav>`:''}<main id="main" tabindex="-1"></main><footer class="site-footer"><div><div class="footer-brand">Fibers of Earth</div><span>An independent field guide by Chaos.</span></div><span>Look closer. Follow the thread.</span><nav class="footer-links" aria-label="Footer"><a href="#/about">About</a><a href="#/sources">Sources & method</a><a href="#/privacy">Privacy</a><a href="https://github.com/SharpMeow/FibersOfEarth" target="_blank" rel="noopener noreferrer">GitHub ↗</a></nav></footer>`;
}
function railItems(selected){const list=getMaterials({...atlasFilter,mapped:true});return list.length?list.map(m=>`<button class="fiber-option ${selected===m.id?'active':''}" data-fiber="${m.id}" ${selected===m.id?'aria-current="true"':''}><span class="mini-swatch" style="--swatch:${m.color}"></span><span><span class="fiber-name">${esc(m.name)}</span><small>${m.family} fiber</small></span><span class="chevron">›</span></button>`).join(''):'<p style="padding:12px;font-size:12px">No mapped fibers match. Try the full material library.</p>';}
function atlas(id,r){const m=byId[id];if(!m||!networks[id])return notFound('This material does not have a mapped journey.');const js=journeys.filter(j=>j.fiber===id);const j=js.find(j=>j.id===r.params.get('journey'))||js[0];title('Atlas');
 $('#main').innerHTML=`<div class="page atlas-page"><section class="atlas-title"><div><div class="eyebrow"><span class="live-dot"></span> A FIELD GUIDE TO WHAT WE WEAR</div><h1>Every thread has a world.</h1></div><p>Discover the materials, places and people behind the cloth. Start with a fiber. Follow its journey.</p></section><section class="atlas-layout" aria-label="Fiber atlas"><aside class="material-rail" aria-label="Choose a mapped fiber"><div class="rail-head"><div class="eyebrow">THE FIBER INDEX</div><span>${Object.keys(networks).length}</span></div><label class="search-field">${icon('search')}<input id="atlas-search" type="search" placeholder="Find a fiber…" value="${esc(atlasFilter.q)}" aria-label="Search mapped fibers"></label><div class="rail-filters"><select id="atlas-family" aria-label="Filter mapped fibers by family">${['All materials','Animal','Plant','Cellulosic','Synthetic','Recycled','Specialty'].map(f=>`<option ${f===atlasFilter.family?'selected':''}>${f}</option>`).join('')}</select><select id="atlas-sort" aria-label="Sort mapped fibers"><option value="featured" ${atlasFilter.sort==='featured'?'selected':''}>Featured</option><option value="az" ${atlasFilter.sort==='az'?'selected':''}>A–Z</option></select></div><div class="rail-list" id="rail-list">${railItems(id)}</div><div class="rail-bottom">${materials.length} materials, brands & technologies.<br><a href="#/materials">Open the complete library ↗</a></div></aside><div class="map-panel"><div class="map-top"><span class="map-caption">THE GLOBAL FIBER ATLAS <span class="muted"> / 01</span></span><div class="segmented" aria-label="Map projection"><button data-map="globe" aria-pressed="true">Globe</button><button data-map="flat" aria-pressed="false">Map</button></div></div><div class="globe" id="globe"></div><span class="map-helper">Drag to explore · select a place to look closer</span><div class="map-bottom"><div class="map-legend"><span><i></i>Origin</span><span><i></i>Processing</span><span><i></i>Destination</span></div><div class="map-tools"><button data-globe="left" aria-label="Rotate globe left">‹</button><button data-globe="right" aria-label="Rotate globe right">›</button><button data-globe="out" aria-label="Zoom out">−</button><button data-globe="in" aria-label="Zoom in">+</button><button data-globe="reset" aria-label="Reset globe">${icon('reset')}</button></div></div></div><aside class="journey-panel"><div class="eyebrow">A FIBER, FOLLOWED</div><h2>${esc(m.name)}</h2><p>${esc(m.tagline)}</p><label class="sr-only" for="atlas-journey">Choose a journey</label><select class="route-select" id="atlas-journey">${js.map(x=>`<option value="${x.id}" ${x.id===j.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><ol class="journey-stops">${j.stops.map(n=>`<li><span class="stop-dot"></span><button data-stop="${n.id}"><span class="stop-name">${esc(n.name)}</span><span class="stop-sub">${esc(n.sub)}</span></button></li>`).join('')}</ol><div class="route-stats"><div><b>${j.countries.length}</b><small>Countries</small></div><div><b>${j.stops.length}</b><small>Stages</small></div><div><b>${Math.round(j.km/1000)}k</b><small>km estimate</small></div></div><a class="button primary" href="#/journey/${j.id}">Explore this journey ${icon('arrow')}</a><a class="text-link" style="font-size:10px;margin-top:12px;align-self:center" href="#/fiber/${id}">Read the material profile</a></aside></section><div class="atlas-footnote"><span>${j.status==='Legacy concept'?'Legacy concept: original connections remain unverified.':'Illustrative connections, not tracked shipments.'} Distance is a great-circle estimate.</span><a href="#/sources">How to read this atlas ↗</a></div><div id="node-detail"></div><div class="section-head"><h2>There’s more in every material.</h2><a class="text-link" href="#/materials">Explore the library ${icon('arrow')}</a></div><div class="discovery-grid">${[['linen','From field to fabric','A plant, a process, a place.'],['cashmere','Beyond the softness','Get to know the fine undercoat.'],['silk','A thread through time','Follow the history of silk.']].map(([id,t,p])=>`<a class="discovery-card" href="#/fiber/${id}">${swatch(byId[id])}<div class="discovery-copy"><div class="eyebrow">${byId[id].family} · ${byId[id].name}</div><h3>${t}</h3><p>${p} ↗</p></div></a>`).join('')}</div></div>`;
 globe=new Globe($('#globe'),networks[id],j,n=>selectNode(n,m));
 function updateRail(){atlasFilter={q:$('#atlas-search').value,family:$('#atlas-family').value,sort:$('#atlas-sort').value};$('#rail-list').innerHTML=railItems(id);}
 $('#atlas-search').addEventListener('input',updateRail);$('#atlas-family').addEventListener('change',updateRail);$('#atlas-sort').addEventListener('change',updateRail);
 $('#atlas-journey').addEventListener('change',e=>{location.hash=href('atlas',id,{journey:e.target.value});});
}
function selectNode(n,m){globe.focus(n);const el=$('#node-detail');el.innerHTML=`<section class="node-detail" aria-live="polite"><div><div class="eyebrow">${esc(n.role)} · ${esc(n.country)}</div><h3>${esc(n.name)}</h3><small class="muted">${Math.abs(n.lat).toFixed(2)}° ${n.lat>=0?'N':'S'} · ${Math.abs(n.lon).toFixed(2)}° ${n.lon>=0?'E':'W'}</small></div><p>${esc(processNote(n,m))}</p><button class="icon-btn" data-action="close-node" aria-label="Close place detail">${icon('close')}</button></section>`;}
function materialCard(m){return `<article class="material-card"><div class="card-image"><a href="#/fiber/${m.id}" aria-label="Explore ${esc(m.name)}">${swatch(m)}<span class="card-id">${String(m.index).padStart(3,'0')}</span></a>${saveButton(m.id,'icon-btn card-save')}</div><div class="material-card-body"><div class="eyebrow">${esc(m.family)}</div><h3><a href="#/fiber/${m.id}">${esc(m.name)}</a></h3><p>${esc(m.tagline)}</p><div class="card-links"><a href="#/fiber/${m.id}">Read profile ${icon('arrow')}</a><a href="#/compare?ids=${m.id},wool,cotton" aria-label="Compare ${esc(m.name)}">Compare ${icon('compare')}</a></div></div></article>`;}
function pager(page,total,size=12){const pages=Math.ceil(total/size);return pages>1?`<div class="pagination"><button class="button small" data-page="${page-1}" ${page===1?'disabled':''}>${icon('left')} Previous</button><span>Page ${page} of ${pages}</span><button class="button small" data-page="${page+1}" ${page>=pages?'disabled':''}>Next ${icon('right')}</button></div>`:'';}
function library(r,brandsOnly=false,savedOnly=false){title(savedOnly?'Saved materials':brandsOnly?'Brands & technologies':'Material library');const defaultFamily=brandsOnly?'Brands & technologies':'All materials';const filters={q:r.params.get('q')||'',family:r.params.get('family')||defaultFamily,sort:r.params.get('sort')||'featured'};
 $('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">${savedOnly?'YOUR FIELD COLLECTION':brandsOnly?'BEHIND THE TRADEMARK':'THE MATERIAL LIBRARY'}</div><h1>${savedOnly?'Keep your curiosity close.':brandsOnly?'A name is only the start.':'Know what you’re wearing.'}</h1><p>${savedOnly?'Your saved materials, kept in this browser.':brandsOnly?'Distinguish a branded fiber from a feedstock, a sourcing program or a way of making yarn.':'A growing reference of natural fibers, manufactured materials and the technologies that connect them. Explore their origins, histories, science and care.'}</p></div>${savedOnly?'<p class="bookmarks-note">Bookmarks stay on this device. They are not uploaded or synced.</p>':''}<div class="toolbar"><label class="search-field">${icon('search')}<input type="search" id="library-search" placeholder="Search materials, uses or trade names…" value="${esc(filters.q)}" aria-label="Search material library"></label>${!brandsOnly?`<label>Family <select id="library-family">${families.map(f=>`<option ${filters.family===f?'selected':''}>${esc(f)}</option>`).join('')}</select></label>`:''}<label>Sort <select id="library-sort">${[['featured','Featured'],['az','Name: A–Z'],['za','Name: Z–A'],['family','Family, then name'],['routes','Mapped journeys first']].map(([v,t])=>`<option value="${v}" ${v===filters.sort?'selected':''}>${t}</option>`).join('')}</select></label><span id="library-count" class="result-count" aria-live="polite"></span><button class="button small" data-action="reset-library">Reset</button></div>${!savedOnly&&!brandsOnly?`<div class="family-chips" aria-label="Popular material groups">${['All materials','Plant','Animal','Cellulosic','Synthetic','Recycled','Technical','Brands & technologies'].map(f=>`<button class="chip ${filters.family===f?'active':''}" data-family="${esc(f)}" aria-pressed="${filters.family===f}">${esc(f)}</button>`).join('')}</div>`:''}<div id="library-results"></div>${!savedOnly?'<div class="notice">Coverage includes fibers, named variants, fillings and branded technologies. It is a broad textile reference, not a claim to list every species, grade or proprietary formulation. Specialty trade routes are marked separately.</div>':''}</div>`;
 let page=Math.max(1,Number(r.params.get('page'))||1);
 function draw(reset=false){if(reset)page=1;filters.q=$('#library-search').value;filters.family=brandsOnly?'Brands & technologies':$('#library-family')?.value||'All materials';filters.sort=$('#library-sort').value;let list=getMaterials(filters);if(savedOnly)list=list.filter(m=>isSaved(m.id));page=Math.max(1,Math.min(page,Math.ceil(list.length/12)||1));setQuery({...filters,page,family:filters.family===defaultFamily?'':filters.family});$('#library-count').textContent=list.length+' entries';$('#library-results').innerHTML=list.length?`<div class="library-grid">${list.slice((page-1)*12,page*12).map(materialCard).join('')}</div>${pager(page,list.length)}`:empty(savedOnly?'Your collection is waiting.':'No materials found.',savedOnly?'Save a material using its bookmark button, then find it here.':'Try a different name, use, or family. You can also reset the filters.');$$('[data-family]').forEach(b=>{b.classList.toggle('active',b.dataset.family===filters.family);b.setAttribute('aria-pressed',b.dataset.family===filters.family);});}
 $('#library-search').addEventListener('input',()=>draw(true));$('#library-family')?.addEventListener('change',()=>draw(true));$('#library-sort').addEventListener('change',()=>draw(true));
 $('#main').addEventListener('click',e=>{const f=e.target.closest('[data-family]');if(f){$('#library-family').value=f.dataset.family;draw(true);}const p=e.target.closest('[data-page]');if(p){page=Number(p.dataset.page);draw();$('#library-results').scrollIntoView({block:'start'});}if(e.target.closest('[data-action="reset-library"]')){$('#library-search').value='';if($('#library-family'))$('#library-family').value='All materials';$('#library-sort').value='featured';draw(true);}});
 draw();
}
function profile(id,tab='overview'){const m=byId[id];if(!m)return notFound();title(m.name);const js=journeys.filter(j=>j.fiber===id);const sci=scienceFor(m.brand?byId[m.base]:m);const tabs=[['overview','Overview'],['history','History'],['science','Science'],['journeys','Journeys'],['care','Care & impact']];if(!tabs.some(t=>t[0]===tab))tab='overview';
 let body='';
 if(tab==='overview')body=`<h2>Meet ${esc(m.name)}.</h2><p>${esc(m.composition)}</p><h3>How it feels</h3><p>${esc(m.feel)}</p><h3>Where you’ll find it</h3><p>${esc(m.uses)}</p>${m.brand?`<div class="notice">${esc(m.type)}. This is a proprietary name, not a new generic fiber classification. <a href="#/fiber/${m.base}">Explore the underlying material →</a></div>`:''}<div class="section-head"><h2>A story woven through time.</h2></div><p>${esc(m.history)}</p><a class="text-link" href="#/fiber/${id}/history">Explore the history ${icon('arrow')}</a>`;
 if(tab==='history')body=`<h2>The story of ${esc(m.name)}.</h2><div class="history-block"><span class="history-icon">01</span><div><h3>From origin to use</h3><p>${esc(m.history)}</p></div></div><div class="history-block"><span class="history-icon">02</span><div><h3>The material today</h3><p>${esc(m.composition)} ${esc(m.uses)}</p></div></div><div class="history-block"><span class="history-icon">03</span><div><h3>The next question</h3><p>${esc(m.question)}</p></div></div><div class="notice">This is a concise historical overview. Precise first-use dates are omitted where the evidence depends on region, product form or disputed attribution.</div>`;
 if(tab==='science')body=`<h2>Inside the material.</h2><div class="eyebrow">CHEMISTRY & STRUCTURE</div><h3>${esc(sci[0])}</h3><p>${esc(sci[1])}</p><h3>From fiber to fabric</h3><p>${esc(m.feel)} The final textile also depends on fiber length, yarn preparation, twist, knit or weave, and finishing.</p><h3>What a label cannot measure</h3><p>A material name alone cannot establish warmth, durability or comfort. Comparable tests need the same conditions and a defined product construction. The atlas uses qualitative descriptions rather than unsupported performance scores.</p><a class="button primary" href="#/science">Open the science lab ${icon('arrow')}</a>`;
 if(tab==='journeys')body=js.length?`<h2>Follow a possible path.</h2><p>Explore ${js.length} named routes through this material’s atlas model. Each connects approximate places and processing stages, without claiming a verified supplier relationship.</p><div class="route-grid profile-routes">${js.map(routeCard).join('')}</div>`:`<h2>A profile without an invented route.</h2><p>This entry has material, historical and technical context. A geographic supply-chain model has not been added. The linked references are a starting point for finding documented producers.</p>${m.brand&&networks[m.base]?`<a class="button" href="#/atlas/${m.base}">Explore the underlying fiber atlas ${icon('arrow')}</a>`:'<a class="button" href="#/journeys">Browse mapped materials →</a>'}`;
 if(tab==='care')body=`<h2>Keep it in use.</h2><p>${esc(m.care)}</p><h3>Tradeoffs worth understanding</h3><p>${esc(m.tradeoff)}</p><div class="notice"><strong>A useful question to ask</strong><br>${esc(m.question)}</div><h3>Care for the whole product</h3><p>Construction, blends, coatings, dyes and trims can change appropriate care. The finished product’s label and producer instructions take priority over general fiber guidance.</p><a class="text-link" href="#/article/care-for-longer">Read the care field note ${icon('arrow')}</a>`;
 const ids=[...m.sources];if(id==='nylon')ids.push('nylon-history');if(['wool','cotton','silk','cashmere'].includes(id))ids.push('trade-history');
 $('#main').innerHTML=`<div class="page">${breadcrumb([['Materials','#/materials'],[m.name]])}<section class="profile-hero"><div><div class="eyebrow">MATERIAL ${String(m.index).padStart(3,'0')} · ${esc(m.family)}</div><h1>${esc(m.name)}</h1><p class="dek">${esc(m.tagline)}</p><div class="actions">${networks[id]?`<a class="button primary" href="#/atlas/${id}">Find it on the atlas ${icon('globe')}</a>`:''}<a class="button" href="#/compare?ids=${id},${id==='wool'?'linen':'wool'},cotton">Compare ${icon('compare')}</a>${saveButton(id)}<button class="button small" data-action="share">${icon('share')} Share</button></div></div><div class="swatch-art ${id==='wool'?'wool':id==='silk'?'silk':''}" style="--swatch:${m.color}"><span class="fiber-ring"></span><span class="profile-art-label">${esc(m.name).toUpperCase()} / ABSTRACT TEXTILE STUDY</span></div></section><nav class="profile-tabs" aria-label="Material sections">${tabs.map(([key,name])=>`<a href="#/fiber/${id}/${key}" ${tab===key?'aria-current="page"':''}>${name}</a>`).join('')}</nav><div class="profile-body"><article class="reading">${m.legacyOnly?'<div class="notice">Specialty archive. Original geographic connections and supplier claims are unverified. No current commercial volumes or performance rankings are asserted.</div>':''}${body}</article><aside><section class="fact-box"><h3>At a glance</h3><div class="fact-row"><small>Family</small>${esc(m.family)}</div><div class="fact-row"><small>Entry type</small>${m.brand?esc(m.type):m.legacyOnly?'Specialty / legacy material':'Fiber or material reference'}</div><div class="fact-row"><small>Map coverage</small>${js.length?js.length+' illustrative journeys':'Reference profile'}</div><div class="fact-row"><small>Science</small>${esc(sci[0])}</div>${m.aliases?`<div class="fact-row"><small>Related search terms</small>${esc(m.aliases)}</div>`:''}</section><section class="fact-box"><h3>Read the sources</h3>${sourceList(ids)}<small class="muted">References explain materials and processes. They do not verify each modeled trade connection.</small></section></aside></div></div>`;
}
function routeCard(j){const m=byId[j.fiber];return `<article class="route-card"><div class="eyebrow">${esc(m.name)} · ${j.stops.length} STAGES</div><h3><a href="#/journey/${j.id}">${esc(j.title)}</a></h3><div class="route-path">${j.stops.map(n=>esc(n.name)).join(' → ')}</div><div class="route-meta"><span>${j.countries.length} countries · ${j.km.toLocaleString()} km*</span><a href="#/journey/${j.id}" aria-label="Explore ${esc(m.name)} journey ${esc(j.title)}">Explore ↗</a></div></article>`;}
function routesPage(r){title('Journey library');const q=r.params.get('q')||'',fiber=r.params.get('fiber')||'all',sort=r.params.get('sort')||'featured';$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">THE JOURNEY LIBRARY</div><h1>Follow a different thread.</h1><p>Explore ${journeys.length} curated paths from the atlas model. Search a material, a city or a country to see how the stages connect.</p></div><div class="toolbar"><label class="search-field">${icon('search')}<input id="journey-search" type="search" value="${esc(q)}" placeholder="Try Biella, Mongolia, or linen…" aria-label="Search journeys"></label><label>Material <select id="journey-fiber"><option value="all">All mapped fibers</option>${getMaterials({mapped:true,sort:'az'}).map(m=>`<option value="${m.id}" ${fiber===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>Sort <select id="journey-sort">${[['featured','Featured'],['az','Origin: A–Z'],['distance-asc','Distance: shortest'],['distance-desc','Distance: longest'],['stages','Most stages']].map(([id,t])=>`<option value="${id}" ${sort===id?'selected':''}>${t}</option>`).join('')}</select></label><span class="result-count" id="journey-count" aria-live="polite"></span></div><div id="journey-results"></div><div class="notice">*Distances sum great-circle segments between approximate markers. They exclude shipping detours and local collection. They are not transport or emissions estimates. Route links are illustrative; specialty legacy concepts remain unverified.</div></div>`;
 let page=Math.max(1,Number(r.params.get('page'))||1);
 function draw(reset=false){if(reset)page=1;const q=$('#journey-search').value,fiber=$('#journey-fiber').value,sort=$('#journey-sort').value;let list=journeys.filter(j=>(fiber==='all'||j.fiber===fiber)&&normalize([byId[j.fiber].name,j.title,...j.countries,...j.stops.map(n=>n.name)].join(' ')).includes(normalize(q)));if(sort==='az')list.sort((a,b)=>a.title.localeCompare(b.title));if(sort==='distance-asc')list.sort((a,b)=>a.km-b.km);if(sort==='distance-desc')list.sort((a,b)=>b.km-a.km);if(sort==='stages')list.sort((a,b)=>b.stops.length-a.stops.length);page=Math.min(page,Math.ceil(list.length/12)||1);setQuery({q,fiber:fiber==='all'?'':fiber,sort,page});$('#journey-count').textContent=list.length+' journeys';$('#journey-results').innerHTML=list.length?`<div class="route-grid">${list.slice((page-1)*12,page*12).map(routeCard).join('')}</div>${pager(page,list.length)}`:empty('No routes match.','Try another place, or choose all mapped fibers.');}
 ['journey-search','journey-fiber','journey-sort'].forEach(id=>$('#'+id).addEventListener(id==='journey-search'?'input':'change',()=>draw(true)));
 $('#main').addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){page=Number(p.dataset.page);draw();$('#journey-results').scrollIntoView();}});draw();
}
function journeyPage(id){const j=journeyById[id];if(!j)return notFound();const m=byId[j.fiber];title(j.title+' · '+m.name);$('#main').innerHTML=`<div class="page">${breadcrumb([['Journeys','#/journeys'],[j.title]])}<section class="journey-hero"><div><div class="eyebrow">${esc(m.name)} · ${j.status.toUpperCase()}</div><h1>${esc(j.title)}</h1><p>${esc(m.tagline)} Follow this possible sequence through collection, transformation and a destination market.</p><div class="actions"><a class="button primary" href="#/atlas/${m.id}?journey=${j.id}">Open interactive atlas ${icon('globe')}</a><button class="button" data-download="${j.id}">${icon('download')} Download route</button><button class="button" data-action="share">${icon('share')} Share</button></div></div><div class="mini-map" id="journey-globe"></div></section><div class="stats-banner"><div><b>${j.stops.length}</b><span>MODELED STAGES</span></div><div><b>${j.countries.length}</b><span>COUNTRIES</span></div><div><b>${j.km.toLocaleString()}</b><span>GREAT-CIRCLE KM</span></div><div><b>${j.status==='Legacy concept'?'Legacy':'Model'}</b><span>EVIDENCE STATUS</span></div></div><div class="notice">${j.status==='Legacy concept'?'This route was inherited from the original atlas and remains unverified.':'This is an educational route model, not a record of actual shipments or a verified brand supply chain.'} Technical references support general processes; they do not establish these commercial relationships.</div><ol class="full-stops">${j.stops.map((n,i)=>`<li><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><div class="eyebrow">${esc(n.role)}</div><h3>${esc(n.name)}</h3><small>${esc(n.country)} · ${esc(n.sub)}</small></div><div><p>${esc(processNote(n,m))}</p><small>${n.lat.toFixed(2)}°, ${n.lon.toFixed(2)}° · Approximate geographic marker</small></div></li>`).join('')}</ol><div class="profile-body"><section class="reading"><h2>What travels between the dots?</h2><p>Raw fiber, prepared top, yarn, fabric and finished garments are different products. The diagram simplifies intermediate warehouses, ports, finishing operations and commercial handoffs. Ask suppliers which material form crosses each stage.</p><h3>One question to keep with you</h3><p>${esc(m.question)}</p><a class="text-link" href="#/fiber/${m.id}">Read the full ${esc(m.name)} profile ${icon('arrow')}</a></section><aside class="fact-box"><h3>Process references</h3>${sourceList(m.sources)}</aside></div></div>`;globe=new Globe($('#journey-globe'),networks[m.id],j,()=>{});globe.flat=true;globe.render();}
function comparePage(r){title('Compare materials');let ids=(r.params.get('ids')||'wool,linen,polyester').split(',').filter(id=>byId[id]).slice(0,3);if(!ids.length)ids=['wool','linen','polyester'];while(ids.length<3)ids.push(['cotton','silk','cashmere'].find(x=>!ids.includes(x)));ids=[...new Set(ids)];while(ids.length<3)ids.push(materials.find(m=>!ids.includes(m.id)).id);const sorted=[...materials].sort((a,b)=>a.name.localeCompare(b.name));$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">SIDE BY SIDE</div><h1>Different fibers. Better questions.</h1><p>Compare three materials by composition, feel, use and care. These qualitative descriptions are a starting point, not a universal performance ranking.</p></div><p class="mobile-only muted">Swipe the table horizontally to compare all three materials.</p><div class="comparison-wrap" tabindex="0" role="region" aria-label="Material comparison, scroll horizontally on smaller screens"><table class="comparison"><caption class="sr-only">Three materials compared by composition, feel, uses, science, history, care and sourcing</caption><thead><tr><th scope="col">Choose your materials</th>${ids.map((id,i)=>`<th scope="col"><label class="sr-only" for="compare-${i}">Material ${i+1}</label><select id="compare-${i}" data-compare="${i}">${sorted.map(m=>`<option value="${m.id}" ${m.id===id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><h3>${esc(byId[id].name)}</h3><a class="text-link" href="#/fiber/${id}">Read profile ↗</a></th>`).join('')}</tr></thead><tbody>${[['Family','family'],['Composition','composition'],['Feel & behavior','feel'],['Common uses','uses'],['History','history'],['Care','care'],['Tradeoffs','tradeoff'],['Ask the maker','question']].map(([label,key])=>`<tr><th scope="row">${label}</th>${ids.map(id=>`<td>${esc(byId[id][key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">Fabric construction, finish and test conditions can change performance substantially. No numeric softness, warmth or sustainability score is assigned to a generic fiber.</div><div class="actions"><button class="button" data-action="share">${icon('share')} Share comparison</button><a class="button" href="#/science">Understand the science ${icon('arrow')}</a></div></div>`;$$('[data-compare]').forEach(el=>el.addEventListener('change',()=>{const next=$$('[data-compare]').map(x=>x.value);if(new Set(next).size!==next.length){toast('Choose three different materials.');el.value=ids[Number(el.dataset.compare)];return;}location.hash=href('compare','',{ids:next.join(',')});}));}
function regionCards(list=regions){return list.map((r,i)=>`<a class="region-card" href="#/region/${r.id}"><div class="region-art" style="--region:${r.color}"><span>REGION ${String(i+1).padStart(2,'0')}</span></div><div class="region-card-content"><h3>${esc(r.name)}</h3><p>${esc(r.subtitle)} ↗</p></div></a>`).join('');}
function regionsPage(){title('Places & regions');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">A GEOGRAPHY OF MATERIALS</div><h1>Places shape the thread.</h1><p>Growing conditions, local knowledge, mills and trade connect the world of textiles. Start with a region to see the materials and modeled journeys that touch it.</p></div><div class="region-grid">${regionCards()}</div></div>`;}
function regionPage(id){const r=regions.find(x=>x.id===id);if(!r)return notFound();title(r.name);const js=journeys.filter(j=>j.countries.some(c=>r.countries.includes(c)));const ms=[...new Set(js.map(j=>j.fiber))].map(id=>byId[id]);$('#main').innerHTML=`<div class="page">${breadcrumb([['Regions','#/regions'],[r.name]])}<div class="page-intro"><div class="eyebrow">${esc(r.subtitle)}</div><h1>${esc(r.name)}</h1><p>${esc(r.intro)}</p></div><div class="notice"><strong>Ask about this region</strong><br>${esc(r.question)}</div><div class="section-head"><h2>Materials in the model</h2><span class="result-count">${ms.length} mapped materials</span></div><div class="library-grid">${ms.map(materialCard).join('')}</div><div class="section-head"><h2>A few paths to follow</h2><a class="text-link" href="#/journeys">All journeys ${icon('arrow')}</a></div><div class="route-grid">${js.slice(0,6).map(routeCard).join('')}</div></div>`;}
function articleCard(a,i){return `<article class="article-card"><a href="#/article/${a.id}"><div class="article-art" style="background:${['#e6e9dd','#ece3d3','#e2e9e3','#e8e1db'][i%4]}"><span>${['Aa','↗','≈','∞','C','↺','◉','?'][i%8]}</span></div><div class="eyebrow">${esc(a.tag)} · ${a.time} MIN READ</div><h3>${esc(a.title)}</h3><p>${esc(a.dek)}</p><small>Read the field note ↗</small></a></article>`;}
function learnPage(){title('Field notes');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">THE FIELD NOTES</div><h1>Look a little closer.</h1><p>Understand the language, craft and tradeoffs of textiles. A reading collection for the curious, from a clothing label to the structure of a thread.</p></div><div class="article-grid">${articles.map(articleCard).join('')}</div><div class="section-head"><h2>Keep exploring.</h2></div><div class="discovery-grid"><a class="fact-box" href="#/science"><div class="eyebrow">INTERACTIVE</div><h3>The science lab</h3><p>Explore weave structures, chemistry and fiber dimensions. ↗</p></a><a class="fact-box" href="#/history"><div class="eyebrow">THROUGH TIME</div><h3>Fiber histories</h3><p>Browse the historical context for all 100 entries. ↗</p></a><a class="fact-box" href="#/glossary"><div class="eyebrow">THE LANGUAGE</div><h3>A textile glossary</h3><p>From bast to worsted, get to know the terms. ↗</p></a></div></div>`;}
function articlePage(id){const a=articles.find(x=>x.id===id);if(!a)return notFound();title(a.title);$('#main').innerHTML=`<div class="page">${breadcrumb([['Field notes','#/learn'],[a.tag]])}<header class="article-heading"><div class="eyebrow">${esc(a.tag)} · ${a.time} MIN READ</div><h1>${esc(a.title)}</h1><p>${esc(a.dek)}</p></header><div class="article-layout"><aside><div class="eyebrow">IN THIS FIELD NOTE</div>${a.sections.map(([h],i)=>`<a href="#section-${i}" data-scroll="section-${i}">${esc(h)}</a>`).join('')}<a href="#/learn">← All field notes</a></aside><article class="reading">${a.sections.map(([h,p],i)=>`<section id="section-${i}"><h2>${esc(h)}</h2><p>${esc(p)}</p></section>`).join('')}<h3>References</h3>${sourceList(a.sources)}<div class="actions"><button class="button" data-action="share">${icon('share')} Share this note</button><a class="button" href="#/sources">Sources & methodology</a></div></article></div><div class="section-head"><h2>Meet the materials.</h2></div><div class="discovery-grid">${a.fibers.map(id=>`<a class="discovery-card" href="#/fiber/${id}">${swatch(byId[id])}<div class="discovery-copy"><div class="eyebrow">${esc(byId[id].family)}</div><h3>${esc(byId[id].name)}</h3><p>Open material profile ↗</p></div></a>`).join('')}</div></div>`;}
function glossaryPage(r){title('Textile glossary');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">THE LANGUAGE OF TEXTILES</div><h1>From bast to worsted.</h1><p>A practical glossary for the things a label, a mill or a maker might tell you.</p></div><div class="toolbar"><label class="search-field">${icon('search')}<input type="search" id="glossary-search" value="${esc(r.params.get('q')||'')}" placeholder="Search a term or definition…" aria-label="Search glossary"></label><span id="glossary-count" class="result-count" aria-live="polite"></span><button class="button small" data-action="expand-glossary">Expand all</button></div><div id="glossary-results" class="glossary-list"></div></div>`;function draw(){const q=$('#glossary-search').value;setQuery({q});const list=Object.entries(glossary).filter(([k,v])=>normalize(k+' '+v).includes(normalize(q)));$('#glossary-count').textContent=list.length+' terms';$('#glossary-results').innerHTML=list.length?list.map(([k,v])=>`<details><summary>${esc(k)}</summary><p>${esc(v)}</p></details>`).join(''):empty('No terms found.','Try a shorter phrase or a different spelling.');}$('#glossary-search').addEventListener('input',draw);draw();}
function historyPage(r){title('Fiber histories');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">MATERIALS THROUGH TIME</div><h1>Before it became a label.</h1><p>Cloth carries histories of craft, trade, invention and labor. Explore concise historical context for each material, then follow its references.</p></div><div class="toolbar"><label class="search-field">${icon('search')}<input id="history-search" type="search" value="${esc(r.params.get('q')||'')}" placeholder="Search a material or historical theme…" aria-label="Search fiber histories"></label><label>Family <select id="history-family">${families.map(f=>`<option ${r.params.get('family')===f?'selected':''}>${esc(f)}</option>`).join('')}</select></label><span id="history-count" class="result-count" aria-live="polite"></span></div><div id="history-results"></div></div>`;let page=1;function draw(reset=false){if(reset)page=1;const q=$('#history-search').value,family=$('#history-family').value;const list=materials.filter(m=>(family==='All materials'||m.family===family)&&normalize(m.name+' '+m.history).includes(normalize(q))).sort((a,b)=>a.name.localeCompare(b.name));page=Math.min(page,Math.ceil(list.length/12)||1);setQuery({q,family});$('#history-count').textContent=list.length+' histories';$('#history-results').innerHTML=list.length?`<div class="history-grid">${list.slice((page-1)*12,page*12).map(m=>`<article class="history-item"><div class="eyebrow">${esc(m.family)}</div><h3><a href="#/fiber/${m.id}/history">${esc(m.name)}</a></h3><p>${esc(m.history)}</p><a class="text-link" href="#/fiber/${m.id}/history">Profile & references ↗</a></article>`).join('')}</div>${pager(page,list.length)}`:empty('No histories found.','Try another name or a broader family.');}$('#history-search').addEventListener('input',()=>draw(true));$('#history-family').addEventListener('change',()=>draw(true));$('#main').addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){page=Number(p.dataset.page);draw();$('#history-results').scrollIntoView();}});draw();}
function sciencePage(){title('Science lab');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">THE SCIENCE LAB</div><h1>A closer look at the thread.</h1><p>Explore how chemistry becomes a fiber, how yarn becomes fabric, and why a single material name can never tell the whole story.</p></div><div class="lab-grid"><section class="lab"><div class="eyebrow">01 / FABRIC STRUCTURE</div><h3>Weave a little understanding.</h3><p>Switch structures to see which yarn passes over the other. Green is warp; gold is weft.</p><div class="segmented" aria-label="Weave structure"><button data-weave="plain" aria-pressed="true">Plain</button><button data-weave="twill" aria-pressed="false">2/2 twill</button><button data-weave="satin" aria-pressed="false">5-end satin</button></div><div class="weave-layout"><div id="weave-grid" class="weave-grid" role="img" aria-label="Plain weave interlacing diagram"></div><p id="weave-description" aria-live="polite"></p></div><small>Schematic only. Yarn spacing, scale and surface texture are simplified.</small></section><section class="lab"><div class="eyebrow">02 / FIBER DIMENSIONS</div><h3>What does denier mean?</h3><p>Denier is linear mass, not diameter. Estimate the diameter of an ideal, solid, circular filament.</p><label>Linear density (denier)<input id="denier" type="number" min="0.01" max="100000" step="0.1" value="5"></label><label>Material density (g/cm³)<input id="density" type="number" min="0.01" max="30" step="0.01" value="1.38"></label><output id="diameter" aria-live="polite"></output><small id="tex-result"></small><small>Assumes a single circular, nonporous filament and a specified density. Multifilament yarns, hollow fibers and irregular cross-sections do not meet this model.</small></section></div><div class="section-head"><h2>Six ideas to keep in mind.</h2></div><div class="science-grid">${scienceTopics.map(([id,h,dek,p],i)=>`<article class="science-card" id="science-${id}"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${id.toUpperCase()}</div><h3>${h}</h3><p><strong>${dek}</strong></p><p>${p}</p></article>`).join('')}</div><div class="notice">The diameter model uses d = √(4000 × denier / (9π × density)), with d in micrometers and density in g/cm³. Tex = denier ÷ 9. It is a dimensional calculation, not a softness test or material certification.</div><div class="profile-body"><section class="reading"><h2>Test the fabric, not just the name.</h2><p>A useful comparison defines temperature, humidity, sample construction, conditioning and method. This atlas deliberately avoids converting qualitative descriptions into artificial laboratory scores.</p><a class="button" href="#/compare">Compare material descriptions ${icon('arrow')}</a></section><aside class="fact-box"><h3>Technical starting points</h3>${sourceList(['woolmark','lenzing','manufactured'])}</aside></div></div>`;
 updateWeave('plain');const update=()=>{const d=Number($('#denier').value),rho=Number($('#density').value);if(!Number.isFinite(d)||!Number.isFinite(rho)||d<.01||rho<.01||d>100000||rho>30){$('#diameter').textContent='Enter valid positive values.';$('#tex-result').textContent='Use denier 0.01–100,000 and density 0.01–30 g/cm³.';return;}$('#diameter').textContent=diameterFromDenier(d,rho).toFixed(2)+' μm';$('#tex-result').textContent=(d/9).toFixed(3)+' tex · idealized diameter';};$('#denier').addEventListener('input',update);$('#density').addEventListener('input',update);update();}
function updateWeave(type){const definitions={plain:'Each warp yarn alternates over and under consecutive weft yarns. Adjacent rows reverse the pattern.',twill:'A two-over, two-under repeat shifts by one position each row, creating a diagonal pattern.',satin:'A five-end, four-over/one-under repeat distributes the binding points. Longer floats can create a smoother-looking surface.'};$('#weave-grid').innerHTML=Array.from({length:100},(_,i)=>{const x=i%10,y=Math.floor(i/10);const over=type==='plain'?(x+y)%2===0:type==='twill'?(x+y)%4<2:(x+2*y)%5!==0;return `<span class="${over?'':'weft'}"></span>`;}).join('');$('#weave-grid').setAttribute('aria-label',type+' weave: '+definitions[type]);$('#weave-description').textContent=definitions[type];$$('[data-weave]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.weave===type));}
function sourcesPage(){title('Sources & methodology');$('#main').innerHTML=`<div class="page"><div class="page-intro"><div class="eyebrow">READING THE ATLAS</div><h1>Curiosity, with a paper trail.</h1><p>Material references, transparent limits and a clear distinction between a geographic model and a verified supply chain.</p></div><div class="profile-body"><article class="reading"><h2>What the atlas shows</h2><p>Fibers of Earth contains ${materials.length} material and technology entries, ${Object.keys(networks).length} mapped material networks, ${journeys.length} named illustrative journeys and ${locations.length} distinct location labels. Counts refer to this edition’s dataset, not the size of the global textile industry.</p><h3>Three kinds of information</h3><p><strong>Material context:</strong> editorial descriptions informed by technical, institutional and producer references. <strong>Illustrative routes:</strong> modeled links between approximate places and stages. <strong>Legacy concepts:</strong> specialty connections inherited from the earlier atlas that have not been independently verified.</p><h3>What a source supports</h3><p>A technical article may explain scouring without verifying a particular mill-to-mill shipment. Producer pages establish how a company describes its technology; they are not independent proof of every environmental or performance claim. Historical summaries omit unsupported exact dates.</p><h3>Map and distance</h3><p>The bundled map uses generalized Natural Earth geometry through World Atlas. Markers represent approximate cities or regions. Distance sums great-circle segments using a spherical Earth radius of 6,371 km. It excludes real transport paths and cannot be converted directly into carbon emissions.</p><h3>Coverage and terminology</h3><p>The library includes generic fibers, selected named variants, fillings, historical materials and proprietary technologies. A branded fiber, recycled feedstock, sourcing program and yarn technology are labeled distinctly. No finite catalog can include every plant species, formulation, trademark or experimental material.</p><h3>Editorial maintenance</h3><p>Edition 2.0, prepared September 2026. Selected technical and producer sources were reviewed during the update; coverage is not a complete fact-check of every historical or geographic claim. Corrections and stronger primary references are welcome through the project repository.</p><button class="button" data-action="export-data">${icon('download')} Download atlas data (JSON)</button></article><aside><section class="fact-box"><h3>What we do not infer</h3><p>No live shipment tracking, market-volume weighting, supplier certification, carbon calculator or universal sustainability score is implied by the map.</p></section><section class="fact-box"><h3>Historical data</h3><p>When the 2025 Textile Exchange report is cited, it describes 2024 production. Older technical references are used for material context, not current market shares.</p></section></aside></div><div class="section-head"><h2>The reference shelf.</h2><span class="result-count">${sources.length} references</span></div><div class="source-grid">${sources.map(s=>`<article class="source-card"><div class="eyebrow">${s.id.startsWith('brand-')?'PRODUCER REFERENCE':'REFERENCE'}</div><h3>${esc(s.name)}</h3><p><strong>${esc(s.title)}</strong></p><p>${esc(s.note)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a></article>`).join('')}</div></div>`;}
function aboutPage(){title('About');$('#main').innerHTML=`<div class="page legal-layout"><div class="eyebrow">ABOUT THIS PROJECT</div><h1>The world is in what we wear.</h1><p>Fibers of Earth is an independent textile atlas by Chaos. It connects materials, places, histories and science so that a familiar label can become the beginning of a better question.</p><h2>Explore in four directions.</h2><p><strong>Atlas</strong> follows an illustrative fiber journey. <strong>Materials</strong> offers profiles, comparisons and saved collections. <strong>Journeys</strong> explores routes and regions. <strong>Learn</strong> connects field notes, science, history and terminology.</p><h2>Made for curiosity.</h2><p>The atlas is an educational reference, not a supplier directory or a record of actual shipments. No brand partnership, certification or endorsement is implied. Proprietary names belong to their respective owners.</p><h2>A local-first field guide.</h2><p>Maps, content, search and interactive tools are bundled into the site. No account is required. Bookmarks stay in your browser. External references open only when you follow their links.</p><div class="actions"><a class="button primary" href="#/atlas/wool">Explore the atlas ${icon('arrow')}</a><a class="button" href="#/sources">Sources & method</a><a class="button" href="https://github.com/SharpMeow/FibersOfEarth" target="_blank" rel="noopener noreferrer">Project repository ↗</a></div></div>`;}
function privacyPage(){title('Privacy');$('#main').innerHTML=`<div class="page legal-layout"><div class="eyebrow">YOUR FIELD GUIDE, YOUR DEVICE</div><h1>Privacy, simply.</h1><h2>What stays in your browser</h2><p>The site stores only your saved material IDs in local storage, under fibersOfEarth.saved.v2. If storage is unavailable, bookmarks work for the current session. Search and comparison choices operate locally and may appear in the URL so that views can be shared.</p><h2>What leaves your device</h2><p>The site has no analytics, account system, advertising code or application backend. When hosted online, the hosting provider receives ordinary requests to load the page and may retain server logs. Following an external reference visits that site under its own policies.</p><h2>Control your collection</h2><p>Remove individual bookmarks from their cards. Use the control below to clear this atlas’s saved collection. Other browser data is unaffected.</p><button class="button" data-action="clear-saved">Clear my saved materials</button><h2>Sharing</h2><p>Share copies the current URL to your clipboard when browser permissions allow. For a local file, the site offers the route fragment without copying your local file path. Download controls create files locally.</p></div>`;}
function notFound(message='That page is not part of the atlas.'){title('Page not found');$('#main').innerHTML=`<div class="page">${empty('A thread we couldn’t follow.',esc(message))}<p style="text-align:center;margin-top:25px"><a class="text-link" href="#/atlas/wool">Return to the atlas ${icon('arrow')}</a></p></div>`;}
function render(focus=true){globe?.destroy();globe=null;const r=route();shell(r);const map={atlas:()=>atlas(r.id||'wool',r),materials:()=>library(r),brands:()=>library(r,true),saved:()=>library(r,false,true),fiber:()=>profile(r.id,r.tab),compare:()=>comparePage(r),journeys:()=>routesPage(r),journey:()=>journeyPage(r.id),regions:regionsPage,region:()=>regionPage(r.id),learn:learnPage,article:()=>articlePage(r.id),science:sciencePage,history:()=>historyPage(r),glossary:()=>glossaryPage(r),sources:sourcesPage,about:aboutPage,privacy:privacyPage};try{(map[r.page]||(()=>notFound()))();}catch(error){console.error(error);notFound('This page could not be loaded. Return to the material library to continue.');}if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}}
function downloadFile(name,data,type='application/json'){const blob=new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Download prepared.');}
async function share(){const value=location.protocol==='file:'?location.hash||'#/atlas/wool':location.href;if(location.protocol==='file:'){showShareFallback(value,'Share this route after opening the atlas. Your local file path is not included.');return;}try{await navigator.clipboard.writeText(value);toast('Link copied.');}catch{showShareFallback(value,'Copy this link to share the current view.');}}
function showShareFallback(value,label){const dialog=$('#search-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="search-title">Share this view</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close share dialog">${icon('close')}</button></div><p>${label}</p><label>Link<input class="share-fallback" readonly value="${esc(value)}"></label>`;dialog.showModal();$('input',dialog).select();}
function openSearch(){const dialog=$('#search-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="search-title">Follow your curiosity.</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close search">${icon('close')}</button></div><label class="search-field">${icon('search')}<input id="global-search" type="search" placeholder="A fiber, a place, a question…" aria-label="Search all materials, journeys and field notes"></label><div id="global-results" class="search-results" aria-live="polite"></div><small class="muted">Search by name, use or trade name. Escape closes search.</small>`;function draw(){const q=$('#global-search').value;const ms=getMaterials({q}).slice(0,8);const as=articles.filter(a=>q&&normalize(a.title+' '+a.dek).includes(normalize(q))).slice(0,3);const js=journeys.filter(j=>q&&normalize(j.title+' '+j.countries.join(' ')).includes(normalize(q))).slice(0,4);$('#global-results').innerHTML=ms.length||as.length||js.length?[...ms.map(m=>`<a class="search-result" href="#/fiber/${m.id}"><strong>${esc(m.name)}</strong><small>Material · ${esc(m.family)}</small></a>`),...as.map(a=>`<a class="search-result" href="#/article/${a.id}"><strong>${esc(a.title)}</strong><small>Field note</small></a>`),...js.map(j=>`<a class="search-result" href="#/journey/${j.id}"><strong>${esc(j.title)}</strong><small>Journey · ${esc(byId[j.fiber].name)}</small></a>`)].join(''):'<p>No matches. Try a fiber name or a country.</p>';}dialog.showModal();$('#global-search').addEventListener('input',draw);draw();$('#global-search').focus();}
document.addEventListener('click',e=>{
 const save=e.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);return;}
 const fiber=e.target.closest('[data-fiber]');if(fiber){location.hash=href('atlas',fiber.dataset.fiber);return;}
 const stop=e.target.closest('[data-stop]');if(stop&&globe){selectNode(globe.n.nodes[stop.dataset.stop],byId[route().id||'wool']);return;}
 const projection=e.target.closest('[data-map]');if(projection&&globe){globe.flat=projection.dataset.map==='flat';globe.render();$$('[data-map]').forEach(b=>b.setAttribute('aria-pressed',b===projection));$$('[data-globe]').forEach(b=>b.disabled=globe.flat);return;}
 const control=e.target.closest('[data-globe]');if(control&&globe){const key=control.dataset.globe;if(key==='left')globe.rotate(20);if(key==='right')globe.rotate(-20);if(key==='in')globe.scale(.1);if(key==='out')globe.scale(-.1);if(key==='reset')globe.reset();return;}
 const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 const weave=e.target.closest('[data-weave]');if(weave){updateWeave(weave.dataset.weave);return;}
 const dl=e.target.closest('[data-download]');if(dl){const j=journeyById[dl.dataset.download];downloadFile('fibers-of-earth-'+j.id+'.json',JSON.stringify({schemaVersion:1,method:'Illustrative route. Great-circle distance between approximate markers; not verified shipments.',...j},null,2));return;}
 const act=e.target.closest('[data-action]')?.dataset.action;
 if(act==='search')openSearch();if(act==='close-dialog')$('#search-dialog').close();if(act==='share')share();if(act==='close-node')$('#node-detail').innerHTML='';
 if(act==='expand-glossary'){const ds=$$('#glossary-results details');const open=ds.some(d=>!d.open);ds.forEach(d=>d.open=open);e.target.closest('button').textContent=open?'Collapse all':'Expand all';}
 if(act==='clear-saved'){saved=[];try{localStorage.removeItem('fibersOfEarth.saved.v2');}catch{}toast('Your saved collection is cleared.');}
 if(act==='export-data')downloadFile('fibers-of-earth-atlas.json',JSON.stringify({schemaVersion:2,edition:'2.0.0',methodology:'Educational illustrative routes. No verified shipments. Historical and technical context, not product certification.',materials,journeys,sources},null,2));
 if(e.target.closest('#search-dialog a[href^="#/"]'))$('#search-dialog').close();
});
document.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(tag)&&!$('#search-dialog').open){e.preventDefault();openSearch();}});
window.addEventListener('hashchange',()=>render());
render(false);
